package com.aistock.prediction.comparison;
import com.fasterxml.jackson.databind.*;import java.math.*;import java.time.*;import java.util.*;import static com.aistock.prediction.comparison.ComparisonRecords.*;import static com.aistock.prediction.comparison.ComparisonEvidenceVerifier.*;
public final class ComparisonCalculator {
 private static final MathContext MC=MathContext.DECIMAL128;private static final BigDecimal H=new BigDecimal("100");
 private final ComparisonEvidenceVerifier verifier;public ComparisonCalculator(){this(Clock.systemUTC());}public ComparisonCalculator(Clock c){verifier=new ComparisonEvidenceVerifier(c);}
 public Calculation calculate(Input in,List<JsonNode> sources){check(sources!=null&&sources.size()==in.instrumentIds().size());var maps=new ArrayList<Map<LocalDate,JsonNode>>();List<LocalDate> trading=null;var refs=new ArrayList<SourceRef>();
  for(int i=0;i<sources.size();i++){var n=sources.get(i);verifier.verify(n);check(in.instrumentIds().get(i).equals(text(n,"instrumentId"))&&in.evidenceIds().get(i).equals(uuid(text(n,"evidenceId"))));var from=LocalDate.parse(text(n,"from"));var to=LocalDate.parse(text(n,"to"));check(!from.isAfter(in.from())&&!to.isBefore(in.to()));var current=new ArrayList<LocalDate>();var calendar=new LinkedHashMap<LocalDate,Boolean>();for(var c:n.path("calendar")){var d=LocalDate.parse(text(c,"date"));if(!d.isBefore(in.from())&&!d.isAfter(in.to())){calendar.put(d,c.path("open").asBoolean());if(c.path("open").asBoolean())current.add(d);}}
   if(i>0){var prior=sources.get(0).path("calendar");var expected=new LinkedHashMap<LocalDate,Boolean>();for(var c:prior){var d=LocalDate.parse(text(c,"date"));if(!d.isBefore(in.from())&&!d.isAfter(in.to()))expected.put(d,c.path("open").asBoolean());}check(calendar.equals(expected));}else trading=current;
   var map=new TreeMap<LocalDate,JsonNode>();for(var d:n.path("days"))map.put(LocalDate.parse(text(d,"date")),d);maps.add(map);refs.add(new SourceRef(text(n,"instrumentId"),uuid(text(n,"evidenceId")),uuid(text(n,"rawVersionId")),text(n,"contentHash"),from,to,Instant.parse(text(n,"capturedAt"))));}
  var common=new ArrayList<LocalDate>();for(var d:trading)if(maps.stream().allMatch(map->map.containsKey(d)&&"VERIFIED".equals(map.get(d).path("priceState").asText())))common.add(d);
  Range actual=common.size()<2?null:new Range(common.get(0),common.get(common.size()-1));var stocks=new ArrayList<StockResult>();
  for(int i=0;i<maps.size();i++){var issues=new ArrayList<DataIssue>();for(var date:trading){var day=maps.get(i).get(date);for(String field:List.of("priceState","volumeState")){var state=day.path(field).asText();if(!"VERIFIED".equals(state))issues.add(new DataIssue(date,field.equals("priceState")?"backwardClose":"volumeShares",state));}}if(actual==null){stocks.add(new StockResult(in.instrumentIds().get(i),missing("NO_COMMON_ENDPOINTS",0,"%"),missing("NO_COMMON_ENDPOINTS",0,"%"),missing("NO_COMMON_ENDPOINTS",0,"%"),missing("NO_COMMON_ENDPOINTS",0,"股"),List.of(),List.copyOf(issues)));continue;}var map=maps.get(i);var dates=trading.stream().filter(d->!d.isBefore(actual.from())&&!d.isAfter(actual.to())).toList();var first=price(map.get(actual.from()));var last=price(map.get(actual.to()));var chart=new ArrayList<ChartPoint>();var prices=new ArrayList<BigDecimal>();var volumes=new ArrayList<BigDecimal>();boolean priceMissing=false,volumeMissing=false;
   for(var date:dates){var d=map.get(date);boolean pv="VERIFIED".equals(d.path("priceState").asText());boolean vv="VERIFIED".equals(d.path("volumeState").asText());chart.add(new ChartPoint(date,pv?format(price(d).divide(first,MC).multiply(H,MC),6):null));if(pv)prices.add(price(d));else priceMissing=true;if(vv)volumes.add(new BigDecimal(text(d,"volumeShares")));else volumeMissing=true;}
   var ret=available(last.divide(first,MC).subtract(BigDecimal.ONE,MC).multiply(H,MC),2,"%",6);Metric vol,mdd,mean;
   if(priceMissing){vol=missing("PRICE_GAP_OR_SUSPENSION",0,"%");mdd=missing("PRICE_GAP_OR_SUSPENSION",0,"%");}else{var peak=prices.get(0);var max=BigDecimal.ZERO;var returns=new ArrayList<BigDecimal>();for(int j=0;j<prices.size();j++){var c=prices.get(j);peak=peak.max(c);max=max.max(BigDecimal.ONE.subtract(c.divide(peak,MC),MC));if(j>0)returns.add(c.divide(prices.get(j-1),MC).subtract(BigDecimal.ONE,MC));}mdd=available(max.multiply(H,MC),prices.size(),"%",6);if(returns.size()<2)vol=missing("INSUFFICIENT_RETURNS",returns.size(),"%");else{var avg=sum(returns).divide(BigDecimal.valueOf(returns.size()),MC);var squared=BigDecimal.ZERO;for(var r:returns){var diff=r.subtract(avg,MC);squared=squared.add(diff.multiply(diff,MC),MC);}var variance=squared.divide(BigDecimal.valueOf(returns.size()-1),MC);vol=available(variance.multiply(BigDecimal.valueOf(252),MC).sqrt(MC).multiply(H,MC),returns.size(),"%",6);}}
   mean=volumeMissing?missing("VOLUME_GAP_OR_SUSPENSION",0,"股"):available(sum(volumes).divide(BigDecimal.valueOf(volumes.size()),MC),volumes.size(),"股",4);stocks.add(new StockResult(in.instrumentIds().get(i),ret,vol,mdd,mean,List.copyOf(chart),List.copyOf(issues)));}
  var sorted=sources.stream().sorted(Comparator.comparing(n->n.path("instrumentId").asText())).toList();return new Calculation(new Range(in.from(),in.to()),actual,FORMULA,"baostock","BACKWARD",252,List.copyOf(stocks),List.copyOf(refs),hash(sorted));
 }
 private static BigDecimal price(JsonNode n){return new BigDecimal(text(n,"backwardClose"));}private static BigDecimal sum(List<BigDecimal> v){return v.stream().reduce(BigDecimal.ZERO,(a,b)->a.add(b,MC));}
 private static String format(BigDecimal n,int scale){return n.setScale(scale,RoundingMode.HALF_UP).toPlainString();}private static Metric available(BigDecimal v,int count,String unit,int scale){return new Metric("AVAILABLE",null,count,format(v,scale),unit);}private static Metric missing(String reason,int count,String unit){return new Metric("UNAVAILABLE",reason,count,null,unit);}
}
